SELECT t.id,t.source_id,s.name AS subject_name,t.state AS raw_status,t.phase AS stage,t.total_count,t.processed_count,t.verified_count,t.added_count,t.updated_count,t.preserved_count,t.unchanged_count,t.present_count,t.missing_count,t.mismatch_count,t.unreachable_count,t.error,t.created_at,t.updated_at FROM media_import_job t LEFT JOIN media_source s ON s.id=t.source_id WHERE t.id=@{businessId}
